// external sort: in -> out using at most CH numbers in memory at a time
void externalSort(const string& in,const string& out,size_t CH){
    ifstream fin(in); vector<string> runs; vector<long long> buf; long long x;
    auto flush=[&](){ if(buf.empty())return; sort(buf.begin(),buf.end());
        string name="run"+to_string(runs.size())+".tmp"; ofstream f(name);
        for(auto v:buf) f<<v<<"\n"; runs.push_back(name); buf.clear(); };
    while(fin>>x){ buf.push_back(x); if(buf.size()==CH) flush(); }
    flush();
    vector<ifstream> fs; for(auto&r:runs) fs.emplace_back(r);
    priority_queue<pair<long long,int>,vector<pair<long long,int>>,greater<>> pq;
    for(int i=0;i<(int)fs.size();i++) if(fs[i]>>x) pq.push({x,i});
    ofstream fout(out);
    while(!pq.empty()){
        auto [v,i]=pq.top(); pq.pop(); fout<<v<<"\n";
        if(fs[i]>>x) pq.push({x,i});
    }
}

