long long ms(vector<int>& a,vector<int>& t,int l,int r){
    if(r-l<=1) return 0;
    int m=(l+r)/2; long long c=ms(a,t,l,m)+ms(a,t,m,r);
    int i=l,j=m,k=l;
    while(i<m||j<r){
        if(j==r||(i<m&&a[i]<=a[j])) t[k++]=a[i++];
        else { c+=m-i; t[k++]=a[j++]; }
    }
    for(int x=l;x<r;x++) a[x]=t[x];
    return c;
}
