long long bestPerimeter(vector<long long> a){
    sort(a.begin(),a.end()); long long S=accumulate(a.begin(),a.end(),0LL), best=-1;
    int n=a.size();
    for(int k=2;k<n;k++){
        int i=0,j=k-1;
        while(i<j){
            long long p=a[i]+a[j];
            if(2*(p+a[k])>=S) j--;            // too big for the half-sum bound
            else { if(p>a[k]) best=max(best,p+a[k]); i++; }
        }
    }
    return best;
}

